<?php $editing=$editing??null; $action=$editing?$resource.'/update/'.$editing['id']:$resource.'/store'; ?>
<div class="page-header"><h2><?= lang($resource) ?></h2></div><div class="row"><div class="col-md-7"><div class="card"><table class="table data-table" data-source="<?= site_url($resource.'/data') ?>" data-fields="name,name_ar,status,action"><thead><tr><th><?= lang('name') ?></th><th><?= lang('arabic_name') ?></th><th><?= lang('status') ?></th><th></th></tr></thead><tbody><?php foreach ($records as $record): ?><tr><td><?= e($record['name']) ?></td><td><?= e($record['name_ar']) ?></td><td><?= e(lang($record['status'])) ?></td><td><a class="btn btn-sm" href="<?= site_url($resource.'/edit/'.$record['id']) ?>"><?= lang('edit') ?></a></td></tr><?php endforeach; ?></tbody></table></div></div><div class="col-md-5"><div class="card"><div class="card-body"><?= validation_errors('<div class="alert alert-danger">','</div>') ?><?= form_open($action) ?><div class="mb-3"><input class="form-control" name="name" value="<?= e(set_value('name',$editing['name']??'')) ?>" placeholder="<?= e(lang('english_name')) ?>" required></div><div class="mb-3"><input class="form-control" name="name_ar" value="<?= e(set_value('name_ar',$editing['name_ar']??'')) ?>" placeholder="<?= e(lang('arabic_name')) ?>" required></div><?php if ($resource==='warehouses'): ?><div class="mb-3"><input class="form-control" name="address" value="<?= e(set_value('address',$editing['address']??'')) ?>" placeholder="<?= e(lang('address')) ?>"></div><?php endif; ?><select class="form-select mb-3" name="status"><option value="active" <?= ($editing['status']??'active')==='active'?'selected':'' ?>><?= lang('active') ?></option><option value="inactive" <?= ($editing['status']??'')==='inactive'?'selected':'' ?>><?= lang('inactive') ?></option></select><button class="btn btn-primary"><?= lang('save') ?></button><?php if ($editing): ?><a class="btn btn-link" href="<?= site_url($resource) ?>"><?= lang('cancel') ?></a><?php endif; ?><?= form_close() ?></div></div></div></div>
